package com.papazone.payment; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="payments") public class PaymentEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long orderId; private double amount; private String method; private String status; private String transactionRef; private Instant createdAt=Instant.now(); public Long getId(){return id;} public Long getOrderId(){return orderId;} public void setOrderId(Long v){orderId=v;} public double getAmount(){return amount;} public void setAmount(double v){amount=v;} public String getMethod(){return method;} public void setMethod(String v){method=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getTransactionRef(){return transactionRef;} public void setTransactionRef(String v){transactionRef=v;} public Instant getCreatedAt(){return createdAt;} }
